import sys

def main():
    data = sys.stdin.read().split('\n')
    if not data or data[0].strip() == '':
        print("ERR")
        return
    k = int(data[0].strip())
    prog = []
    for i in range(1, k + 1):
        prog.append(data[i].strip() if i < len(data) else '')
    stack = []
    pc = 0
    steps = 0
    out = []
    ok = True
    while True:
        if pc < 0 or pc >= k:
            ok = False
            break
        if steps >= 10000:
            ok = False
            break
        steps += 1
        parts = prog[pc].split()
        if not parts:
            ok = False
            break
        op = parts[0]
        if op == 'HALT':
            break
        elif op == 'PUSH':
            stack.append(int(parts[1]))
            pc += 1
        elif op == 'POP':
            if not stack:
                ok = False
                break
            stack.pop()
            pc += 1
        elif op in ('ADD', 'SUB', 'MUL'):
            if len(stack) < 2:
                ok = False
                break
            a = stack.pop()
            b = stack.pop()
            if op == 'ADD':
                stack.append(b + a)
            elif op == 'SUB':
                stack.append(b - a)
            else:
                stack.append(b * a)
            pc += 1
        elif op == 'DUP':
            if not stack:
                ok = False
                break
            stack.append(stack[-1])
            pc += 1
        elif op == 'SWAP':
            if len(stack) < 2:
                ok = False
                break
            stack[-1], stack[-2] = stack[-2], stack[-1]
            pc += 1
        elif op == 'PRINT':
            if not stack:
                ok = False
                break
            out.append(str(stack.pop()))
            pc += 1
        elif op == 'JNZ':
            if not stack:
                ok = False
                break
            v = stack.pop()
            if v != 0:
                t = int(parts[1])
                if t < 0 or t >= k:
                    ok = False
                    break
                pc = t
            else:
                pc += 1
        else:
            ok = False
            break
    if ok:
        sys.stdout.write('\n'.join(out))
        if out:
            sys.stdout.write('\n')
    else:
        sys.stdout.write('ERR\n')

main()
